package com.yeeyuan;
import java.util.*;
import java.net.*;
import java.net.http.HttpClient;
import java.time.*;
import java.sql.Timestamp;
import java.nio.charset.StandardCharsets;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.*;
import org.springframework.http.client.JdkClientHttpRequestFactory;
import org.springframework.web.client.RestClient;
import static com.yeeyuan.Db.*;
@Service
public class Payments {
 final Db db;final Orders orders;final Settings config;final RestClient gateway;final org.springframework.transaction.support.TransactionTemplate tx;
 public Payments(Db db,Orders orders,Settings config,org.springframework.transaction.PlatformTransactionManager tm){this.db=db;this.orders=orders;this.config=config;this.tx=new org.springframework.transaction.support.TransactionTemplate(tm);var factory=new JdkClientHttpRequestFactory(HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).followRedirects(HttpClient.Redirect.NEVER).build());factory.setReadTimeout(Duration.ofSeconds(10));gateway=RestClient.builder().baseUrl("https://api.omise.co").requestFactory(factory).defaultHeaders(h->{h.setBasicAuth(config.omiseSecretKey(),"");h.set("Omise-Version",config.omiseApiVersion());}).build();}
 @Transactional public Map<String,Object> create(Auth.User u,UUID order,UUID key){String path="/orders/"+order+"/payment-attempts";var cached=orders.cached(u,path,key,Map.of("method","PROMPTPAY"));if(cached!=null)return cached;var o=db.one("SELECT * FROM orders WHERE id=? AND customer_id=? FOR UPDATE",order,u.id());if(!str(o,"status").equals("AWAITING_PAYMENT")||time(o,"payment_deadline").isBefore(Instant.now()))throw new Problem(409,"PAYMENT_CLOSED","ออเดอร์นี้ไม่พร้อมชำระเงิน");var active=db.jdbc.queryForList("SELECT * FROM payment_attempt WHERE order_id=? AND status IN ('CREATING','UNKNOWN','PENDING')",order);if(!active.isEmpty())return view(uuid(active.get(0),"id"),u);UUID id=UUID.randomUUID();boolean mock=config.mockPayments();db.jdbc.update("INSERT INTO payment_attempt(id,order_id,ref_id,provider_charge_id,status,amount_satang,currency,livemode,expires_at) VALUES(?,?,?,?,?,?,'THB',?,?)",id,order,id.toString(),mock?"mock_"+id:null,mock?"PENDING":"CREATING",num(o,"total_satang"),config.omiseSecretKey().startsWith("skey_live_"),o.get("payment_deadline"));db.jdbc.update("UPDATE orders SET payment_status='PENDING',version=version+1 WHERE id=?",order);if(!mock)db.jdbc.update("INSERT INTO outbox_event(topic,aggregate_id,dedupe_key,payload) VALUES('CREATE_CHARGE',?,?,?::jsonb)",id,"charge:"+id,db.encode(Map.of("attemptId",id)));var result=view(id,u);orders.cache(u,path,key,Map.of("method","PROMPTPAY"),result);return result;}
 public Map<String,Object> view(UUID id,Auth.User u){var a=db.one("SELECT p.* FROM payment_attempt p JOIN orders o ON o.id=p.order_id WHERE p.id=? AND o.customer_id=?",id,u.id());var out=new LinkedHashMap<String,Object>();out.put("id",id);out.put("status",a.get("status"));out.put("amountSatang",a.get("amount_satang"));out.put("expiresAt",time(a,"expires_at").toString());out.put("qrUrl",a.get("qr_document_path")==null?null:config.apiBaseUrl()+"/payment-attempts/"+id+"/qr");out.put("demo",config.mockPayments());return out;}
 @Transactional public void simulate(Auth.User u,UUID order){if(!config.local()||!config.mockPayments())throw new Problem(404,"NOT_FOUND","ไม่พบรายการ");var o=db.one("SELECT * FROM orders WHERE id=? AND customer_id=? FOR UPDATE",order,u.id());if(time(o,"payment_deadline").isBefore(Instant.now()))throw Problem.bad("หมดเวลาชำระแล้ว");var a=db.one("SELECT * FROM payment_attempt WHERE order_id=? ORDER BY created_at DESC LIMIT 1",order);apply(uuid(a,"id"),Map.of("id",str(a,"provider_charge_id"),"amount",num(a,"amount_satang"),"currency","thb","status","successful","livemode",false,"paid_at",Instant.now().toString()));}
 @SuppressWarnings("unchecked") Map<String,Object> retrieve(String charge){if(!charge.matches("chrg(_test)?_[a-z0-9]+"))throw Problem.bad("Gateway charge ID ไม่ถูกต้อง");return gateway.get().uri("/charges/{id}",charge).retrieve().body(Map.class);}
 @SuppressWarnings("unchecked") void generate(UUID id){var a=db.one("SELECT * FROM payment_attempt WHERE id=?",id);if(a.get("provider_charge_id")!=null){apply(id,retrieve(str(a,"provider_charge_id")));return;}if(str(a,"status").equals("UNKNOWN")){
   for(int page=0;page<10;page++){Map<String,Object> response=gateway.get().uri("/charges?limit=100&offset="+(page*100)+"&order=reverse_chronological").retrieve().body(Map.class);var data=Orders.maps(response.get("data"));for(var c:data)if(id.toString().equals(str(c,"ref_id"))){apply(id,c);return;}if(data.size()<100)break;}
   throw new Problem(503,"PAYMENT_UNKNOWN","รายการยังรอยืนยัน ห้ามออก charge ใหม่");
  }
  if(time(a,"expires_at").isBefore(Instant.now())){db.jdbc.update("UPDATE payment_attempt SET status='EXPIRED' WHERE id=? AND status='CREATING'",id);return;}
  try{var form=new org.springframework.util.LinkedMultiValueMap<String,String>();form.add("amount",str(a,"amount_satang"));form.add("currency","thb");form.add("source[type]","promptpay");form.add("expires_at",time(a,"expires_at").toString());form.add("ref_id",id.toString());form.add("metadata[attemptId]",id.toString());form.add("metadata[orderId]",str(a,"order_id"));Map<String,Object> charge=gateway.post().uri("/charges").contentType(MediaType.APPLICATION_FORM_URLENCODED).body(form).retrieve().body(Map.class);apply(id,charge);}catch(RuntimeException e){db.jdbc.update("UPDATE payment_attempt SET status='UNKNOWN',last_error_code='CREATE_UNCERTAIN',next_check_at=now()+interval '60 seconds' WHERE id=? AND status='CREATING'",id);throw e;}
 }
 public void apply(UUID id,Map<String,Object> c){tx.executeWithoutResult(ignored->applyLocked(id,c));}
 void applyLocked(UUID id,Map<String,Object> c){if(c==null)throw Problem.bad("Gateway ไม่คืนข้อมูล");var found=db.one("SELECT order_id FROM payment_attempt WHERE id=?",id);UUID order=uuid(found,"order_id");var o=db.one("SELECT * FROM orders WHERE id=? FOR UPDATE",order);var a=db.one("SELECT * FROM payment_attempt WHERE id=? FOR UPDATE",id);if(str(a,"status").equals("SUCCEEDED"))return;String charge=str(c,"id");if(a.get("provider_charge_id")!=null&&!str(a,"provider_charge_id").equals(charge))throw Problem.bad("Charge ไม่ตรงกับ attempt");boolean live=Boolean.TRUE.equals(c.get("livemode"));if(live!=Boolean.TRUE.equals(a.get("livemode")))throw Problem.bad("test/live mode ไม่ตรง");String status=str(c,"status");long amount=((Number)c.get("amount")).longValue();boolean match=amount==num(a,"amount_satang")&&str(c,"currency").equalsIgnoreCase("THB");
  if(status.equals("successful")){Instant paid=c.get("paid_at")==null?Instant.now():Instant.parse(str(c,"paid_at"));db.jdbc.update("UPDATE payment_attempt SET provider_charge_id=?,status='SUCCEEDED',provider_status=?,actual_amount_satang=?,paid_at=?,fee_satang=?,fee_vat_satang=?,net_satang=?,verified_at=now(),updated_at=now() WHERE id=?",charge,status,amount,Timestamp.from(paid),c.get("fee"),c.get("fee_vat"),c.get("net"),id);long other=db.jdbc.queryForObject("SELECT count(*) FROM payment_attempt WHERE order_id=? AND id<>? AND status='SUCCEEDED'",Long.class,order,id);boolean late=!str(o,"status").equals("AWAITING_PAYMENT")||paid.isAfter(time(o,"payment_deadline"));if(!match||other>0||late){String kind=!match?"AMOUNT_MISMATCH":other>0?"DUPLICATE_PAYMENT":"LATE_PAYMENT";db.jdbc.update("UPDATE orders SET payment_status='REVIEW',status=CASE WHEN status IN ('AWAITING_PAYMENT','EXPIRED','CANCELLED') THEN 'ON_HOLD' ELSE status END,version=version+1 WHERE id=?",order);db.jdbc.update("INSERT INTO payment_incident(order_id,attempt_id,kind,details) VALUES(?,?,?,?::jsonb)",order,id,kind,db.encode(Map.of("actualAmountSatang",amount,"expectedAmountSatang",num(a,"amount_satang"))));return;}
   db.jdbc.update("UPDATE orders SET status='QUEUED',payment_status='PAID',version=version+1,updated_at=now() WHERE id=?",order);db.jdbc.update("UPDATE inventory_reservation SET status='CONSUMED',updated_at=now() WHERE order_id=? AND status='HELD'",order);db.jdbc.update("INSERT INTO kitchen_ticket(order_id,station,status) SELECT DISTINCT order_id,station,'QUEUED' FROM order_item WHERE order_id=? ON CONFLICT(order_id,station) DO NOTHING",order);db.event(order,"AWAITING_PAYMENT","QUEUED",null,"Gateway payment verified");db.audit(null,"PAYMENT_VERIFIED",order);orders.notify(order,"PAID");return;
  }
  if(!match)throw Problem.bad("ยอด Gateway ไม่ตรง");String internal=switch(status){case "pending"->"PENDING";case "failed"->"FAILED";case "expired"->"EXPIRED";default->"UNKNOWN";};String qr=null;Object source=c.get("source");if(source instanceof Map<?,?> s&&s.get("scannable_code") instanceof Map<?,?> sc&&sc.get("image") instanceof Map<?,?> image&&image.get("download_uri")!=null)qr=String.valueOf(image.get("download_uri"));if(qr!=null)qrUri(qr);db.jdbc.update("UPDATE payment_attempt SET provider_charge_id=?,status=?,provider_status=?,qr_document_path=COALESCE(?,qr_document_path),verified_at=now(),next_check_at=now()+interval '60 seconds',check_count=check_count+1,updated_at=now() WHERE id=?",charge,internal,status,qr,id);
 }
 static URI qrUri(String url){URI u=URI.create(url);if(!"https".equals(u.getScheme())||!"api.omise.co".equals(u.getHost())||u.getPort()!=-1||u.getUserInfo()!=null||!u.getPath().startsWith("/charges/"))throw Problem.bad("QR URL ไม่อยู่ในผู้ให้บริการที่อนุญาต");return u;}
 public ResponseEntity<byte[]> qr(Auth.User u,UUID id){view(id,u);var a=db.one("SELECT * FROM payment_attempt WHERE id=?",id);if(a.get("qr_document_path")==null||!str(a,"status").equals("PENDING"))throw new Problem(404,"QR_NOT_READY","QR ยังไม่พร้อมหรือปิดรับชำระแล้ว");var response=gateway.get().uri(qrUri(str(a,"qr_document_path"))).retrieve().toEntity(byte[].class);byte[] data=response.getBody();if(data==null||data.length>262144)throw Problem.bad("QR image ไม่ถูกต้อง");String content=new String(data,StandardCharsets.UTF_8);MediaType type=response.getHeaders().getContentType();if(type==null||!(type.isCompatibleWith(MediaType.IMAGE_PNG)||type.toString().startsWith("image/svg+xml")))throw Problem.bad("รูป QR ไม่รองรับ");if(type.toString().startsWith("image/svg+xml")&&(content.toLowerCase(Locale.ROOT).matches("(?s).*(<script|<!doctype|<!entity|<foreignobject|javascript:|\\bonload\\s*=).*")))throw Problem.bad("รูป QR ไม่ปลอดภัย");return ResponseEntity.ok().header("Content-Security-Policy","default-src 'none'; sandbox").header("Cache-Control","no-store").contentType(type).body(data);}
 @Transactional public void inbox(String provider,String eventId,String type,Map<String,Object> payload,String hash){if(eventId==null||eventId.isBlank()||eventId.length()>150)throw Problem.bad("Event ID ไม่ถูกต้อง");db.jdbc.update("INSERT INTO webhook_inbox(provider,event_id,event_type,payload,body_hash) VALUES(?,?,?,?::jsonb,?) ON CONFLICT(provider,event_id) DO NOTHING",provider,eventId,type,db.encode(payload),hash);}
}
